const KONTUR = '#1d1b1a';
const ton = (K, f) => (f > 0 ? hell(K.c, f) : f < 0 ? dunkel(K.c, -f) : K.c);

export function b26Zeichner(S, t, p) {
  const D = B26_DATEN[p.b26];
  if (!D) return;
  if (!S.tex && p.muster && p.muster !== 'uni' && istMuster(p.muster)) S.tex = musterFuellung(S, p.muster);
  // Musterfeld: ein gewähltes Muster (Q37, auch uni) ersetzt das Muster aus dem Bild
  const mAktiv = !!p.muster37 || (!!p.muster && p.muster !== 'uni');
  const K = [S];
  const n = 1 + Math.max(0, ...D.regionen.filter((r) => r[0] === 't' || r[0] === 'r' || r[0] === 'm').map((r) => r[1]));
  for (let i = 1; i < n; i++) K.push(materialDefs(p.farben?.[i - 1] ?? 'grau', p.materialien?.[i - 1] ?? 'baumwolle', S.defs));
  const m37 = p.muster37 && p.muster37 !== 'uni';
  if (p.glatt) K.forEach((k, i) => { if (i > 0 || (!m37 && (!p.muster || p.muster === 'uni'))) if (k.m === 'strick' || k.m === 'kaschmir' || k.m === 'merino') k.tex = null; });
  // eigene Muster je Nebenzone (p.zmuster: Schlüssel aus q37-muster.js, z. B. gestreifter Kragen)
  (p.zmuster ?? []).forEach((mu, i) => { if (mu && K[i + 1]) K[i + 1].tex = musterFuellung(K[i + 1], mu) ?? K[i + 1].tex; });
  // Fell (p.fell: Liste der Zonen): kurze Haarstriche statt Stoffstruktur
  let fell = null;
  if (p.fell) { fell = S.id + 'fl'; S.defs.push(`<pattern id="${fell}a" width="2.3" height="3.1" patternUnits="userSpaceOnUse" patternTransform="rotate(12)"><path d="M0.3 0.1 q0.35 1.2 0 2.5 M1.5 1.3 q0.3 1 -0.1 2.2" stroke="#fff" stroke-opacity="0.16" stroke-width="0.3" fill="none" stroke-linecap="round"/></pattern><pattern id="${fell}b" width="3.7" height="2.7" patternUnits="userSpaceOnUse" patternTransform="rotate(-9)"><path d="M0.9 0.4 q0.3 1.1 -0.05 2.1 M2.7 -0.3 q0.35 1 0 2" stroke="#000" stroke-opacity="0.15" stroke-width="0.3" fill="none" stroke-linecap="round"/></pattern>`); p.fell.forEach((z) => { if (K[z]) { K[z].tex = `url(#${fell}a)`; K[z].tex2 = `url(#${fell}b)`; } }); }
  let rip = null;
  if (D.regionen.some((r) => r[0] === 'r')) { rip = S.id + 'rp'; S.defs.push(`<pattern id="${rip}" width="1.15" height="4" patternUnits="userSpaceOnUse"><rect width="0.45" height="4" fill="#000" opacity="0.28"/><rect x="0.5" width="0.25" height="4" fill="#fff" opacity="0.08"/></pattern>`); }
  const clip = S.id + 'b26';
  S.defs.push(`<clipPath id="${clip}"><path d="${D.kontur}" fill-rule="evenodd"/></clipPath>`);
  t.push(`<ellipse cx="50" cy="${D.boden + 1.8}" rx="${Math.min(32, D.breite * 0.45).toFixed(1)}" ry="2.4" fill="#000" opacity="0.08"/>`);
  t.push(`<g clip-path="url(#${clip})">`);
  for (const r of D.regionen) {
    const d = r[r.length - 1];
    if (r[0] === 'k') t.push(`<path d="${d}" fill="${KONTUR}"/>`);
    else if (r[0] === 'f') t.push(`<path d="${d}" fill="${r[1]}"/>`);
    else if (r[0] === 'm' && !mAktiv) t.push(`<path d="${d}" fill="${r[3]}"/>`);
    else if (r[0] === 'r') { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); t.push(`<path d="${d}" fill="url(#${rip})"/>`); }
    else { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[0] === 'm' ? 0 : r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); if (k.tex2) t.push(`<path d="${d}" fill="${k.tex2}"/>`); }
  }
  // Häkel- und Netzstruktur (p.netz): versetzte Maschenlöcher über dem Stoff, Kontur bleibt darüber sichtbar
  if (p.netz) { const id = S.id + 'nz', nzo = helligkeit(S.c) > 0.7 ? 0.22 : 0.4; S.defs.push(`<pattern id="${id}" width="3" height="3" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0 H3 M0 0 V3" stroke="#fff" stroke-opacity="0.3" stroke-width="0.7"/><circle cx="1.5" cy="1.5" r="0.75" fill="#000" opacity="${nzo}"/></pattern>`);
    for (const r of D.regionen) if (r[0] !== 'k' && r[0] !== 'f') t.push(`<path d="${r[r.length - 1]}" fill="url(#${id})"/>`); }
  // fehlende Kontur im B-Bild ergänzen (innen liegende Hälfte des Strichs, Stärke wie die Bildkontur)
  if (D.rand) t.push(`<path d="${D.kontur}" fill="none" stroke="${KONTUR}" stroke-width="1.5"/>`);
  // Licht von links wie alle Stoffe (stoff.js); Glanzlichter stecken schon in den Tonflächen
  t.push(`<path d="${D.kontur}" fill="url(#${S.id}l)" fill-rule="evenodd"/>`);
  t.push('</g>');
}
